import { z } from "zod";

/**
 * Precise code navigation, backed by SCIP indexes generated by the worker.
 *
 * Positions are 0-based and expressed in UTF-16 code units (what CodeMirror uses).
 * This module is shared between the client and the server.
 */

export const preciseCodeNavStatusRequestSchema = z.object({
    repoName: z.string(),
    revisionName: z.string().optional(),
});
export type PreciseCodeNavStatusRequest = z.infer<typeof preciseCodeNavStatusRequestSchema>;

export const preciseCodeNavStatusResponseSchema = z.object({
    /** Whether a completed index exists for the requested revision. */
    available: z.boolean(),
    commitHash: z.string().optional(),
    indexes: z.array(z.object({
        indexer: z.string(),
        commitHash: z.string(),
        status: z.enum(['PENDING', 'IN_PROGRESS', 'COMPLETED', 'FAILED']),
        error: z.string().optional(),
        completedAt: z.string().optional(),
    })),
});
export type PreciseCodeNavStatusResponse = z.infer<typeof preciseCodeNavStatusResponseSchema>;

export const symbolPositionSchema = z.object({
    repoName: z.string(),
    revisionName: z.string().optional(),
    path: z.string(),
    /** 0-based line. */
    line: z.number().int().min(0),
    /** 0-based UTF-16 offset within the line. */
    character: z.number().int().min(0),
});
export type SymbolPosition = z.infer<typeof symbolPositionSchema>;

export const preciseHoverResponseSchema = z.object({
    symbol: z.string(),
    isLocal: z.boolean(),
    /** The range of the occurrence under the cursor. */
    range: z.object({
        startLine: z.number(),
        startChar: z.number(),
        endLine: z.number(),
        endChar: z.number(),
    }),
    displayName: z.string().optional(),
    kind: z.string().optional(),
    signature: z.string().optional(),
    documentation: z.string().optional(),
}).nullable();
export type PreciseHoverResponse = z.infer<typeof preciseHoverResponseSchema>;

export const preciseRelatedSymbolsRequestSchema = symbolPositionSchema.extend({
    kind: z.enum(['definitions', 'references']),
});
export type PreciseRelatedSymbolsRequest = z.infer<typeof preciseRelatedSymbolsRequestSchema>;

export const preciseMatchSchema = z.object({
    line: z.number(),
    startChar: z.number(),
    endLine: z.number(),
    endChar: z.number(),
    lineContent: z.string(),
    isDefinition: z.boolean(),
});
export type PreciseMatch = z.infer<typeof preciseMatchSchema>;

export const preciseFileMatchesSchema = z.object({
    repoId: z.number(),
    repoName: z.string(),
    repoDisplayName: z.string().optional(),
    /** Revision to use when linking to the file. */
    revisionName: z.string(),
    path: z.string(),
    language: z.string(),
    matches: z.array(preciseMatchSchema),
});
export type PreciseFileMatches = z.infer<typeof preciseFileMatchesSchema>;

export const preciseRelatedSymbolsResponseSchema = z.object({
    symbol: z.string().optional(),
    matchCount: z.number(),
    /** True when results were capped. */
    truncated: z.boolean(),
    files: z.array(preciseFileMatchesSchema),
});
export type PreciseRelatedSymbolsResponse = z.infer<typeof preciseRelatedSymbolsResponseSchema>;
